package com.zhuqiyun.platform;
import com.zhuqiyun.finance.FinanceService;
import com.zhuqiyun.project.ProjectService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import static com.zhuqiyun.domain.Rules.*;

/** Shared SQL scope and filters for screen pages and exports. Only fixed SQL identifiers are accepted. */
@Service
public class RecordQueryService {
 private final Db db;private final Auth auth;private final FinanceService finance;private final ProjectService projects;
 public RecordQueryService(Db db,Auth auth,FinanceService finance,ProjectService projects){this.db=db;this.auth=auth;this.finance=finance;this.projects=projects;}
 private record Spec(String permission,String select,String from,String alias,String search,String scope){}
 private Spec spec(String entity){String scope=auth.projectFilter("p");String joins=" JOIN projects p ON p.id=t.project_id";
  return switch(entity){
   case "suppliers","materials","warehouses"->new Spec("master:read","t.*"," FROM "+entity+" t","t","t.code,t.name","t.tenant_id=1");
   case "projects","cost-overview"->new Spec(entity.equals("projects")?"project:read":"cost:read","p.*,u.name manager_name"," FROM projects p JOIN users u ON u.id=p.manager_id","p","p.code,p.name,u.name",scope);
   case "plan-history"->new Spec("contract:read","t.id,t.contract_id,t.created_at,u.name operator_name"," FROM contract_plan_history t JOIN contracts c ON c.id=t.contract_id JOIN projects p ON p.id=c.project_id JOIN users u ON u.id=t.operator_id","t","c.code,c.name,u.name",scope);
   case "plan-allocations"->{auth.require("contract:read");yield new Spec("finance:read","t.*,s.stage_name,u.name operator_name,COALESCE(a.reference,r.reference) source_reference,CASE WHEN t.payment_id IS NOT NULL THEN 'PAYMENT' ELSE 'REFUND' END source_type"," FROM contract_payment_allocations t JOIN contracts c ON c.id=t.contract_id JOIN projects p ON p.id=c.project_id JOIN contract_payment_stages s ON s.id=t.stage_id JOIN users u ON u.id=t.operator_id LEFT JOIN payments a ON a.id=t.payment_id LEFT JOIN supplier_refunds r ON r.id=t.refund_id","t","s.stage_name,u.name,a.reference,r.reference",scope);}
   case "project-progress"->new Spec("project:read","t.*,u.name operator_name"," FROM project_progress t"+joins+" JOIN users u ON u.id=t.operator_id","t","t.note,p.name,u.name",scope);
   case "approval-records","request-approvals"->{if(entity.equals("approval-records"))auth.require("request:approve");yield new Spec("request:read","t.*,r.code request_code,p.name project_name,u.name operator_name"," FROM approvals t JOIN purchase_requests r ON r.id=t.request_id JOIN projects p ON p.id=r.project_id JOIN users u ON u.id=t.operator_id","t","r.code,p.name,u.name,t.comment",scope);}
   case "quotes"->new Spec("quote:read","t.*,r.code request_code,p.name project_name,s.name supplier_name"," FROM quotes t JOIN purchase_requests r ON r.id=t.request_id JOIN projects p ON p.id=r.project_id JOIN suppliers s ON s.id=t.supplier_id","t","r.code,p.name,s.name",scope);
   case "purchase-returns"->new Spec("order:read","t.*,p.name project_name,u.name operator_name"," FROM purchase_returns t"+joins+" JOIN users u ON u.id=t.operator_id","t","t.code,t.reference,t.reason,p.name",scope);
   case "requests"->new Spec("request:read","t.*,p.name project_name,u.name applicant_name"," FROM purchase_requests t"+joins+" JOIN users u ON u.id=t.applicant_id","t","t.code,p.name,u.name",scope);
   case "orders"->new Spec("order:read","t.*,t.total_amount-t.closed_amount-COALESCE((SELECT SUM(r.amount) FROM purchase_returns r WHERE r.order_id=t.id),0) effective_amount,p.name project_name,s.name supplier_name,u.name buyer_name"," FROM purchase_orders t"+joins+" JOIN suppliers s ON s.id=t.supplier_id JOIN users u ON u.id=t.buyer_id","t","t.code,p.name,s.name",scope);
   case "contracts"->new Spec("contract:read","t.*,p.name project_name,s.name supplier_name,o.code order_code"," FROM contracts t"+joins+" LEFT JOIN suppliers s ON s.id=t.supplier_id LEFT JOIN purchase_orders o ON o.id=t.order_id","t","t.code,t.name,p.name,s.name",scope);
   case "expenses"->new Spec("cost:read","t.*,p.name project_name,u.name operator_name"," FROM costs t"+joins+" JOIN users u ON u.id=t.operator_id","t","t.description,p.name",scope);
   case "receipts","issues","issue-returns"->{String table=entity.equals("issue-returns")?"issue_returns":entity;String extra=entity.equals("receipts")?",o.code order_code":entity.equals("issue-returns")?",o.code issue_code":"";String link=entity.equals("receipts")?" JOIN purchase_orders o ON o.id=t.order_id":entity.equals("issue-returns")?" JOIN issues o ON o.id=t.issue_id":"";yield new Spec("inventory:read","t.*,p.name project_name,w.name warehouse_name,u.name operator_name"+extra," FROM "+table+" t"+joins+" JOIN warehouses w ON w.id=t.warehouse_id JOIN users u ON u.id=t.operator_id"+link,"t","t.code,t.reference,p.name,w.name",scope);}
   case "stocktakes"->{auth.require("inventory:company");yield new Spec("stocktake:read","t.*,w.name warehouse_name,u.name applicant_name,v.name reviewer_name"," FROM stocktakes t JOIN warehouses w ON w.id=t.warehouse_id JOIN users u ON u.id=t.applicant_id LEFT JOIN users v ON v.id=t.reviewer_id","t","t.code,w.name,u.name","t.tenant_id=1");}
   case "inventory"->{auth.require("inventory:company");yield new Spec("inventory:read","t.*,w.name warehouse_name,m.name material_name,m.specification,m.unit,m.safety_stock"," FROM inventory t JOIN warehouses w ON w.id=t.warehouse_id JOIN materials m ON m.id=t.material_id","t","w.name,m.code,m.name,m.specification","t.tenant_id=1");}
   case "stock-movements"->new Spec("inventory:read","t.*,p.name project_name,w.name warehouse_name,m.name material_name,m.unit,u.name operator_name"," FROM stock_movements t LEFT JOIN projects p ON p.id=t.project_id JOIN warehouses w ON w.id=t.warehouse_id JOIN materials m ON m.id=t.material_id JOIN users u ON u.id=t.operator_id","t","t.reference,p.name,w.name,m.name","t.tenant_id=1 AND (("+scope+")"+(auth.can("stocktake:read")&&auth.can("inventory:company")?" OR t.project_id IS NULL":"")+")");
   case "payables","supplier-statement"->new Spec("finance:read","t.*,GREATEST(t.amount-t.paid_amount,0) outstanding_amount,GREATEST(t.paid_amount-t.amount,0) refundable_amount,p.name project_name,s.name supplier_name,o.code order_code,o.total_amount order_amount"," FROM payables t"+joins+" JOIN suppliers s ON s.id=t.supplier_id JOIN purchase_orders o ON o.id=t.order_id","t","o.code,p.name,s.name",scope);
   case "payments","payment-applications","supplier-refunds"->{String table=entity.equals("payment-applications")?"payment_applications":entity.equals("supplier-refunds")?"supplier_refunds":"payments";String person=entity.equals("payment-applications")?"applicant_id":"operator_id";yield new Spec("finance:read","t.*,a.project_id,a.order_id,p.name project_name,s.name supplier_name,o.code order_code,u.name "+(entity.equals("payment-applications")?"applicant_name":"operator_name")," FROM "+table+" t JOIN payables a ON a.id=t.payable_id JOIN projects p ON p.id=a.project_id JOIN suppliers s ON s.id=a.supplier_id JOIN purchase_orders o ON o.id=a.order_id JOIN users u ON u.id=t."+person,"t","o.code,p.name,s.name"+(entity.equals("payment-applications")?"":",t.reference"),scope);}
   default->throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND,"不支持的业务列表");};
 }
 @Transactional(readOnly=true) public Map<String,Object> page(String entity,Map<String,String> filters,int max){Spec s=spec(entity);auth.require(s.permission);int page=integer(filters.getOrDefault("page","1")),size=integer(filters.getOrDefault("size","20"));Fields.check(page>=1&&page<=100000&&size>=1&&size<=max,"分页参数无效");List<Object> args=new ArrayList<>();String where=s.scope;
  String q=filters.getOrDefault("q","").trim();Fields.check(q.length()<=100,"搜索内容过长");if(!q.isEmpty()){List<String> clauses=new ArrayList<>();for(String c:s.search.split(",")){clauses.add(c+" LIKE ?");args.add("%"+q.replace("!","!!").replace("%","!%").replace("_","!_")+"%");}where+=" AND ("+String.join(" OR ",clauses.stream().map(c->c+" ESCAPE '!'").toList())+")";}
  if(filters.containsKey("status")&&!filters.get("status").isBlank()){Fields.check(Set.of("suppliers","projects","cost-overview","requests","orders","contracts","payment-applications","stocktakes").contains(entity),"此列表不支持状态筛选");String status=filters.get("status");Fields.check(status.matches("[A-Z_]{1,30}"),"状态格式无效");where+=" AND "+s.alias+".status=?";args.add(status);}
  if("quotes".equals(filters.get("queue"))&&entity.equals("requests"))where+=" AND t.status IN ('APPROVED','ORDERED')";
  for(String key:List.of("project_id","supplier_id","warehouse_id","material_id","order_id","request_id","contract_id","id"))if(filters.containsKey(key)&&!filters.get(key).isBlank()){
   String column=s.alias+"."+key;
   if(key.equals("request_id"))column="t.request_id";
   if(key.equals("project_id")){Fields.check(!Set.of("suppliers","materials","warehouses","inventory","stocktakes").contains(entity),"列表不支持项目筛选");column="p.id";}
   if(key.equals("order_id")&&Set.of("payments","payment-applications","supplier-refunds").contains(entity))column="a.order_id";
   if(key.equals("supplier_id")&&Set.of("payments","payment-applications","supplier-refunds").contains(entity))column="a.supplier_id";
   Fields.check(allowedFilter(entity,key),"列表不支持此关联筛选");where+=" AND "+column+"=?";args.add(Fields.id(filters.get(key)));
  }
  if("true".equals(filters.get("low_only"))&&entity.equals("inventory"))where+=" AND t.quantity<m.safety_stock";
  if((filters.containsKey("date_from")||filters.containsKey("date_to"))&&Set.of("suppliers","materials","warehouses","payables","supplier-statement","inventory").contains(entity))Fields.check(false,"此列表无制单日期，不能按日期筛选");
  if(filters.containsKey("date_from")&&!filters.get("date_from").isBlank()){where+=" AND "+s.alias+".created_at>=?";args.add(Fields.date(filters.get("date_from"))+" 00:00:00");}
  if(filters.containsKey("date_to")&&!filters.get("date_to").isBlank()){where+=" AND "+s.alias+".created_at<?";args.add(java.time.LocalDate.parse(Fields.date(filters.get("date_to"))).plusDays(1)+" 00:00:00");}
  String from=s.from+" WHERE "+where;long total=((Number)db.one("SELECT COUNT(*) total"+from,args.toArray()).get("total")).longValue();List<Object> paged=new ArrayList<>(args);paged.add(size);paged.add((long)(page-1)*size);var rows=db.list("SELECT "+s.select+from+" ORDER BY "+s.alias+".id DESC LIMIT ? OFFSET ?",paged.toArray());var access=DataPolicy.flags(auth);
  List<Map<String,Object>> result=new ArrayList<>();for(var r:rows){long id=((Number)r.get("id")).longValue();
   if(entity.equals("projects")||entity.equals("cost-overview")){r=DataPolicy.project(r,access);if(entity.equals("cost-overview"))r.putAll(projects.metrics(id));}
   if(entity.equals("purchase-returns")&&!auth.can("cost:read"))for(String key:List.of("stock_amount","variance_amount","cost_id"))r.remove(key);
   if(Set.of("inventory","stock-movements","issues","issue-returns").contains(entity))r=DataPolicy.inventory(r,access);
   if(Set.of("payables","supplier-statement").contains(entity)){r.putAll(finance.payableView(id));if(!auth.can("order:read"))r.remove("order_amount");r.put("original_paid_amount",db.one("SELECT COALESCE(SUM(amount),0) amount FROM payments WHERE payable_id=?",id).get("amount"));r.put("receipt_amount",db.one("SELECT COALESCE(SUM(amount),0) amount FROM receipts WHERE order_id=?",r.get("order_id")).get("amount"));r.put("return_amount",db.one("SELECT COALESCE(SUM(amount),0) amount FROM purchase_returns WHERE order_id=?",r.get("order_id")).get("amount"));}
   if(entity.equals("payments")||entity.equals("supplier-refunds")){String col=entity.equals("payments")?"payment_id":"refund_id";r.put("unallocated_amount",dec(r.get("amount")).subtract(dec(db.one("SELECT COALESCE(SUM(amount),0) n FROM contract_payment_allocations WHERE "+col+"=? AND voided=FALSE",id).get("n"))));}
   if(entity.equals("quotes"))r.put("items",db.list("SELECT i.*,ri.material_id,ri.quantity,m.name material_name,m.specification,m.unit FROM quote_items i JOIN request_items ri ON ri.id=i.request_item_id JOIN materials m ON m.id=ri.material_id WHERE i.quote_id=? ORDER BY i.id",id));
   if(entity.equals("receipts"))r.put("items",db.list("SELECT i.*,m.name material_name,m.specification,m.unit,i.quantity-COALESCE((SELECT SUM(a.quantity) FROM purchase_return_items a WHERE a.receipt_item_id=i.id),0) returnable_quantity FROM receipt_items i JOIN materials m ON m.id=i.material_id WHERE i.receipt_id=? ORDER BY i.id",id));
   if(entity.equals("issues")){var lines=db.list("SELECT t.id,t.material_id,m.name material_name,m.specification,m.unit,-t.quantity quantity,t.amount,COALESCE((SELECT SUM(r.quantity) FROM issue_return_items r WHERE r.source_movement_id=t.id),0) returned_quantity,-t.quantity-COALESCE((SELECT SUM(r.quantity) FROM issue_return_items r WHERE r.source_movement_id=t.id),0) returnable_quantity FROM stock_movements t JOIN materials m ON m.id=t.material_id WHERE t.issue_id=? AND t.kind='ISSUE' ORDER BY t.id",id);r.put("items",lines.stream().map(l->DataPolicy.inventory(l,access)).toList());}result.add(r);
  }return row("items",result,"total",total,"page",page,"size",size);
 }
 private boolean allowedFilter(String e,String k){return switch(k){case "id"->true;case "contract_id"->Set.of("plan-history","plan-allocations").contains(e);case "request_id"->Set.of("quotes","approval-records","request-approvals").contains(e);case "project_id"->!Set.of("suppliers","materials","warehouses","inventory","stocktakes").contains(e);case "supplier_id"->Set.of("quotes","orders","contracts","payables","supplier-statement","payments","payment-applications","supplier-refunds").contains(e);case "warehouse_id","material_id"->Set.of("inventory","stock-movements").contains(e)||k.equals("warehouse_id")&&Set.of("receipts","issues","issue-returns","stocktakes").contains(e);case "order_id"->Set.of("purchase-returns","receipts","contracts","payables","supplier-statement","payments","payment-applications","supplier-refunds").contains(e);default->false;};}
 private int integer(String value){try{return Integer.parseInt(value);}catch(Exception e){Fields.check(false,"分页参数无效");return 0;}}
}
